def _resolve_model_language(lang: str | list[str] | None) -> _ModelLanguages:
    """Select the model language based on the requested OCR language(s).

    English assets are used only when an English language token is present and
    no Chinese token is requested; otherwise the general-purpose Chinese models
    are used (this is also the fallback for an empty or unknown language).
    """
    if lang is None:
        return _RAPIDOCR_LANG_CHINESE
    tokens = [lang] if isinstance(lang, str) else list(lang)
    normalized = [str(token).strip().lower() for token in tokens]
    has_english = any(token in ("en", "english") for token in normalized)
    has_chinese = any(token in ("ch", "zh", "chinese") for token in normalized)
    if has_english and not has_chinese:
        return _RAPIDOCR_LANG_ENGLISH
